TEST(TelemetryTest, BsonLargeUint64_timestamp_us)
{
    telemetry::Telemetry in, out;
    static const uint8_t big[] = {
        0x13, 0x74, 0x69, 0x6d, 0x65, 0x73, 0x74, 0x61,
        0x6d, 0x70, 0x5f, 0x75, 0x73, 0x00, 0xff, 0xff,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x40, 0x30,
    };
    static const uint8_t edge[] = {
        0x12, 0x74, 0x69, 0x6d, 0x65, 0x73, 0x74, 0x61,
        0x6d, 0x70, 0x5f, 0x75, 0x73, 0x00, 0xff, 0xff,
        0xff, 0xff, 0xff, 0xff, 0xff, 0x7f,
    };
    in.Set_timestamp_us(UINT64_C(18446744073709551615));
    std::string bytes = in.to_bson();
    ASSERT_NE(std::string::npos, bytes.find(std::string(reinterpret_cast<const char*>(big), sizeof(big))));
    ASSERT_TRUE(out.from_bson(bytes));
    ASSERT_EQ(in, out);
    in.Set_timestamp_us(UINT64_C(9223372036854775807));
    bytes = in.to_bson();
    ASSERT_NE(std::string::npos, bytes.find(std::string(reinterpret_cast<const char*>(edge), sizeof(edge))));
    ASSERT_TRUE(out.from_bson(bytes));
    ASSERT_EQ(in, out);
}

